window.RS_CASES=[{"id":"growth","name":"The Billion-Rupee Bluff","sector":"BANKING · STRATEGY","role":"Independent strategy partner","mandate":"At fictional Aster Bank, the CEO has promised ₹100 crore additional recurring annual pre-tax operating contribution within 18 months. New investments need a business case; the branch network and risk appetite are fixed. The board wants an independent decision.","skills":["Problem framing","Evidence","Economics","Decision design","Execution"],"steps":[{"area":"Framing","phase":"Mandate","title":"The denominator in the boardroom","prompt":"The CEO has promised ₹100 crore incremental annual recurring pre-tax operating contribution by month 18. The CFO says the number has no agreed starting point. Which brief would you request?","find":["Product-wise gross revenue growth and the CEO's aspirational run-rate","A reconciled contribution bridge specifying baseline, cost allocation, one-offs and what counts as genuinely incremental","A peer comparison of assets and deposits over three years"],"best":1,"why":"An unambiguous measure is a prerequisite to a falsifiable strategy.","exhibit":"Finance confirms annual recurring pre-tax contribution of ₹420 crore, excluding one-offs. The ₹100 crore promise must be incremental to this baseline and after additional distribution and platform costs.","question":"What growth on the existing annual contribution baseline must the programme create?","choices":[],"answer":23.81,"reason":"₹100 crore / ₹420 crore = 23.81%. This is not gross revenue or a share of a larger, projected denominator.","type":"number","unit":"%","tolerance":0.08,"id":"growth-1"},{"title":"Find the first crack","prompt":"Your CEO gives you a single statistic: 1.5 million retail customers and almost no net contribution growth. What do you investigate before suggesting a campaign?","find":["Customer counts and product holdings","Contribution by segment and cost-to-serve","Technology vendor catalogue"],"best":1,"why":"Accounts are an activity measure, not the economic outcome. Contribution by segment establishes where value is actually created and destroyed.","exhibit":"The CFO's finance pack shows 220,000 customers generate 87% of positive contribution; 710,000 are loss-making after servicing costs. The gap is concentration and economics, not the customer count.","question":"Which initial diagnosis has the strongest support?","choices":["The bank must acquire customers faster","The portfolio has a contribution-distribution problem","Every customer needs an AI offer engine","The problem is necessarily branch productivity"],"answer":1,"reason":"Concentration and negative contribution are measurable. Acquisition, branches and AI are interventions or hypotheses, not evidenced causes.","area":"Framing","id":"growth-2","phase":"Mandate"},{"area":"Commercial reasoning","phase":"Economics","title":"Two identical wins?","prompt":"The deposits head celebrates two ₹200 crore balance improvements. The finance controller refuses to add both to value creation. What would you examine?","find":["Net-new external inflows, internal transfers, margins, acquisition incentives and marginal funding costs","Deposit growth by acquisition channel only","A sector benchmark for average deposit balances"],"best":0,"why":"Balance shifts do not necessarily add bank-wide economic value.","exhibit":"Pool A: ₹200 crore outside money; net annual margin 2.1%; ₹0.9 crore campaign cost. Pool B: ₹200 crore internally transferred; incremental funding benefit ₹0.3 crore; ₹0.6 crore campaign cost.","question":"What is combined first-year net contribution after these costs in ₹ crore?","choices":[],"answer":3,"reason":"A: (200 × 2.1%) − 0.9 = ₹3.3 crore. B: 0.3 − 0.6 = −₹0.3 crore. Combined ₹3.0 crore, not ₹400 crore times a generic margin.","type":"number","unit":"₹ crore","tolerance":0.08,"id":"growth-3"},{"area":"Investigation","phase":"Discovery","title":"Where is the reachable market?","prompt":"A marketing leader claims hundreds of thousands of latent opportunities from an inactive population. You may ask only one follow-up before funding a pilot.","find":["Revenue deciles and a product-sales dashboard","Intersect product demand signals, eligibility, permissions and reachable channels by unique customer","Compare how many branches sell each product"],"best":1,"why":"Opportunity requires both probable demand and the ability to execute a permissible treatment.","exhibit":"760,000 low-activity customers; 180,000 show external demand; 72,000 are eligible; 45,000 of those are currently consented and contactable. The numbers describe nested groups.","question":"Which is the defensible pilot denominator?","choices":["180,000: observed demand","72,000: meets underwriting criteria","45,000: eligible, permissioned and reachable","760,000: full dormant population"],"answer":2,"reason":"Only 45,000 are simultaneously demand-qualified, eligible, permissioned and reachable. Revenue modelling on the larger groups would overstate executable reach.","id":"growth-4"},{"title":"Challenge the obvious explanation","prompt":"Marketing proposes targeting all low-activity customers. What evidence would distinguish unmet demand from unprofitable outreach?","find":["Customer age distribution","Out-of-bank product holdings, contactability and margin potential","A list of potential chatbot providers"],"best":1,"why":"Opportunity exists only where a relevant need, profitable product and reachable channel overlap.","exhibit":"Among 710,000 loss-making customers, 160,000 show external product demand; 58,000 are contactable and eligible for the bank's relevant offer. The remaining customers have no established conversion economics.","question":"What is the defensible addressable base for an initial test?","choices":["710,000","160,000","58,000","1,500,000"],"answer":2,"reason":"Demand alone is not addressability. Contactability and eligibility narrow the initial feasible test population to 58,000.","area":"Evidence & data","id":"growth-5","phase":"Discovery"},{"area":"Evidence & data","phase":"Discovery","title":"A mismatch of seventeen thousand","prompt":"Analytics presents 62,000 prospects while the calling system reports 45,000. The analysts say neither source is wrong. Which check has the highest information value?","find":["Refresh-time and identity reconciliation of permission, duplicate customers and eligibility between the mart and dialler","A new enterprise data-platform RFP","A sample of promotional messages from sales"],"best":0,"why":"The same customer at a different time and system can produce contradictory counts without either team misreporting.","exhibit":"The mart is refreshed weekly; the calling system checks permission daily. Duplicate keys and changed consent states explain 17,000 surplus mart records. Both teams counted accurately within their local definitions.","question":"What should production selection enforce?","choices":["Averaging both counts to 53,500","Source-of-truth identity plus execution-time consent and eligibility gates","Using whichever system offers higher volumes","Modelled probabilities of missing customer permission"],"answer":1,"reason":"Decision-time permission and identity are hard gates. A statistical estimate cannot authorise contact.","id":"growth-6"},{"area":"Execution","phase":"Operating model","title":"Sixty thousand leads. Then silence.","prompt":"Sales says AI isn't useful. The model team says downstream execution is failing. Which trace would arbitrate their disagreement?","find":["Lead assignment, channel attempts, disposition events and rejection reasons with timestamps","The model's confusion matrix only","Territory-level quarterly deposit growth"],"best":0,"why":"A decision model is only as useful as the source-to-action funnel and its feedback.","exhibit":"Monthly lead funnel: 60,000 generated → 48,000 allocated → 19,200 queued → 7,680 attempted → 1,920 reached. The dialler lacks timely disposition feedback for most leads.","question":"What percentage of original leads results in actual contact?","choices":[],"answer":3.2,"reason":"1,920 / 60,000 = 3.2%. Improving ranking without fixing the chain may have low near-term returns.","type":"number","unit":"%","tolerance":0.06,"id":"growth-7"},{"title":"Request causal evidence","prompt":"A pilot reports 11% activation. What do you demand before inferring that outreach worked?","find":["A comparison with a randomly assigned no-contact holdout","The overall campaign-open rate","A more accurate propensity model"],"best":0,"why":"The counterfactual distinguishes activation caused by outreach from activity that would have occurred anyway.","exhibit":"In a random pilot of 100,000 contactable customers, 11% activate after outreach versus 8% in a comparable holdout. The contribution per incremental activation is ₹1,800/year; contact cost is ₹45 per contacted customer.","question":"What is the approximate incremental annual net contribution before platform costs?","type":"number","answer":9,"tolerance":0.1,"unit":"₹ lakh","reason":"(11% − 8%) × 100,000 × ₹1,800 = ₹54 lakh contribution; outreach costs ₹45 lakh; net = ₹9 lakh.","area":"Commercial reasoning","id":"growth-8","phase":"Evidence"},{"area":"Evidence & data","phase":"Causal test","title":"A counterfactual arrives","prompt":"The business says 11% of contacted customers activated a product, calling it AI-generated growth. What data would you require for attribution?","find":["A randomised no-treatment holdout with identical eligibility and a complete cost ledger","Last month's gross application totals","The model's offline ranking AUC"],"best":0,"why":"The economically relevant question is what happened because of the treatment.","exhibit":"100,000 customers in the test; 11% activation with contact, 8% without. Each incremental activation yields ₹1,800 annual contribution; contact costs ₹45 per target. Platform costs another ₹20 lakh annually.","question":"Calculate annual incremental net contribution after full stated costs in ₹ lakh.","choices":[],"answer":-11,"reason":"3,000 incremental activations × ₹1,800 = ₹54 lakh. Contact costs ₹45 lakh, licence ₹20 lakh. Net −₹11 lakh. The proposed platform is not justified by this pilot economics alone.","type":"number","unit":"₹ lakh","tolerance":0.1,"id":"growth-9"},{"title":"A late invoice","prompt":"The technology team now quotes ₹20 lakh annual platform costs. What is the prudent action?","find":["Full rollout delivery timeline","Pilot sensitivity and cheaper operational alternatives","A vendor's accuracy benchmark"],"best":1,"why":"A negative net pilot needs a revised unit-economic plan, not a bigger purchase order.","exhibit":"At the current scale, annualised incremental net contribution is ₹9 lakh before a ₹20 lakh licence. A simpler workflow costs ₹4 lakh annually and could be tested with a narrower, higher-margin cohort.","question":"What should the investment committee authorise?","choices":["Buy the platform immediately","Scale the exact pilot to everyone","Test the cheaper workflow on higher-margin cohorts with a holdout","Reject all future cross-sell work"],"answer":2,"reason":"The existing economics are negative with the platform. A bounded comparison using higher-value cohorts can test whether the mechanism is viable.","area":"AI & controls","id":"growth-10","phase":"Economics"},{"area":"Technology design","phase":"Enablers","title":"The architecture meeting","prompt":"The CTO proposes replacing the campaign platform. Data engineering thinks a narrower investment could repair the decision loop. What specification should precede procurement?","find":["Trusted identity/permission gates, source-to-action latency, governed integration and disposition events","AI model selection and its parameter count","A single system to hold all data regardless of purpose"],"best":0,"why":"Architect for the operating decision before selecting tools.","exhibit":"Core systems expose daily product status; an API can deliver eligible leads. Dialler dispositions arrive as a weekly CSV, preventing near-term learning. A governed event feedback contract is feasible without a platform replacement.","question":"Which first-release architecture solves the established gap?","choices":["Daily eligible cohorts with permission check, API delivery, event-level dispositions and controlled holdout outcomes","A generic LLM attached to the existing weekly spreadsheet","Full enterprise platform migration ahead of deciding the use case","Expose raw source tables to every channel agent"],"answer":0,"reason":"Close the measurable source-to-action-and-learning loop first. A new platform is only justified if specific service-level gaps remain.","id":"growth-11"},{"area":"AI & controls","phase":"Intervention","title":"The highest AUC loses","prompt":"A new vendor model ranks customers better in validation, yet Finance questions its commercial case. What would you compare?","find":["Incremental margin per constrained contact slot after treatment costs and guardrails","Raw AUC, assuming conversion value follows automatically","Total parameter count and inference benchmark"],"best":0,"why":"Predictive ranking is not the same as incremental decision value.","exhibit":"Model A: AUC 0.82, expected ₹180 incremental net value/contact on the eligible pilot group. Model B: AUC 0.86, expected ₹130. Each reaches 50,000 eligible contact slots within current policy.","question":"What is Model A's economic advantage at that capacity in ₹ lakh?","choices":[],"answer":25,"reason":"(₹180 − ₹130) × 50,000 = ₹25 lakh. Further uncertainty testing remains needed; the comparison demonstrates why AUC is not the objective.","type":"number","unit":"₹ lakh","tolerance":0.15,"id":"growth-12"},{"title":"Design an AI boundary","prompt":"Operations requests an autonomous agent to select offers and execute them. What do you validate first?","find":["Where decision authority and customer permission sit","Number of slides in the AI roadmap","The newest available foundation model"],"best":0,"why":"Eligibility, consent and authority are prerequisite controls for any automated offers.","exhibit":"The bank permits AI to rank eligible next-best-actions, but regulated pricing exceptions and customer-facing commitments need an accountable human or approved policy workflow.","question":"Which architecture respects the decision boundary?","choices":["LLM chooses and sends any offer without review","Rules gate eligibility and consent; model ranks offers; approved channels execute with logging","Model bypasses risk eligibility if prediction is confident","Send every offer to every customer"],"answer":1,"reason":"Bounded autonomy: hard policy gates before model rankings, controlled execution, and an auditable trail.","area":"AI & controls","id":"growth-13","phase":"Intervention"},{"area":"Commercial reasoning","phase":"Investment","title":"The scale trap","prompt":"The CFO shows that the highest-ranked customers respond profitably. The CEO assumes those returns extend to the remainder. What would you challenge?","find":["Non-linear response and margin by score band, volume limits and fixed execution costs","Whether promotional content should be translated","The vendor's software availability SLA"],"best":0,"why":"Marginal value may fall sharply as the programme exhausts the highest-value opportunities.","exhibit":"Top 10,000 customers: ₹210 incremental net contribution/contact. Next 40,000: ₹48/contact. Bottom 50,000: −₹20/contact. Fixed annual operating costs: ₹22 lakh.","question":"What is the net annual contribution from targeting all 100,000 in ₹ lakh?","choices":[],"answer":8.2,"reason":"₹21 lakh + ₹19.2 lakh − ₹10 lakh − ₹22 lakh = ₹8.2 lakh. The right target set may be smaller than the apparent market.","type":"number","unit":"₹ lakh","tolerance":0.1,"id":"growth-14"},{"title":"Defend the rollout","prompt":"The CEO demands a 90-day plan and measurable success. Which evidence should determine expansion?","find":["Incremental margin and complaints versus persistent holdout","Number of AI-generated offers","Raw campaign impressions"],"best":0,"why":"The decision concerns incremental risk-adjusted economics and customer impact, not outputs of the tool.","exhibit":"Business can support two 4-week cohorts with weekly monitoring. Finance will validate contribution; Risk owns consent and exceptions; Tech owns availability and logging.","question":"Choose a credible expansion gate.","choices":["Expand if opens exceed 15%","Expand if model AUC improves","Expand if holdout-adjusted net contribution is positive after full costs and guardrails hold","Expand if the pilot reaches 100,000 customers"],"answer":2,"reason":"Net incremental contribution after all costs, within risk and experience limits, is the causal business result.","area":"Execution","id":"growth-15","phase":"Intervention"},{"area":"Execution","phase":"Boardroom","title":"A difficult approval","prompt":"The CEO wants the chairperson to ratify the full ₹100 crore promise today. The CFO says none of the pilots support that certainty. You must put forward a position.","find":["A staged programme with contribution bridge, control groups, named owners, risk limits and kill rules","A full platform purchase plus performance-linked vendor contract","A complete halt because one small pilot had negative economics"],"best":0,"why":"Commit to what is evidenced and preserve an option to invest in what remains unproven.","exhibit":"A 90-day evidence-building phase can test separate deposit, lending and cost-to-serve levers; none has yet demonstrated enough net contribution to validate ₹100 crore by month 18.","question":"What recommendation is defensible?","choices":["Certify ₹100 crore based on the reachable-market estimate","Approve stage-gated discovery and pilots; do not certify an unproven target as an outcome","Reject all customer growth investments indefinitely","Count infrastructure readiness as equivalent to recurring contribution"],"answer":1,"reason":"Approve the evidence and execution plan, not a speculative number. Require a quantified bridge with attributable contribution, risk constraints and stop conditions.","id":"growth-16"}],"teaser":"The board has approved an ambition. Nobody agrees on how it could be delivered."},{"id":"fraud","name":"2:17 AM. Code Red.","sector":"PAYMENTS · OPERATIONAL RISK","role":"Independent risk and operating-model adviser","mandate":"Fictional Northstar Payments faces surging alerts, customer complaints and investigation queues after a threshold change. The board must balance actual fraud exposure, customer harm and responsible technology investment.","skills":["Problem framing","Evidence","Economics","Decision design","Execution"],"steps":[{"area":"Framing","title":"The briefing at 2:17","prompt":"The head of payments says 'alerts doubled'. The CRO reports potential losses, the COO reports blocked legitimate payments. What do you ask them to agree on first?","find":["A trace of alerted transactions to confirmed loss, wrongful declines, rules and operational capacity","The fraud software vendor's standard incident benchmark","A comparison of alerts per employee across competitors"],"best":0,"why":"First separate the safety outcome, legitimate-customer harm and the process that produced each.","exhibit":"Alert events rose from 48,000 to 100,000/day after a threshold change. Confirmation labels lag by 21 days. Complaints have risen; investigators can process 2,000 cases/day.","question":"Which claim is currently defensible?","choices":["The threshold change has proven that fraud doubled","Alerts measure policy output; realised fraud and false-block harm require separate evidence","The rules should be rolled back because complaints increased","Investigator capacity is sufficient because confirmed fraud is low"],"answer":1,"reason":"An alert is neither an independent fraud incidence nor proof of prevented loss. We need matched outcomes and timing to adjudicate harm.","id":"fraud-1","phase":"Mandate"},{"title":"Separate volume from harm","prompt":"Fraud alerts doubled in six weeks. What evidence do you seek first?","find":["Total alert volume only","Confirmed bad outcomes, legitimate declines, thresholds and base rates","Vendor demo schedule"],"best":1,"why":"Alert growth can reflect better detection, rule drift or false positives. Outcomes and denominators distinguish them.","exhibit":"100,000 daily alerts, 600 confirmed frauds, 12,000 legitimate transactions blocked, and 2,000 investigations/day capacity. The rules were tightened without a controlled shadow test.","question":"What is the most urgent diagnostic?","choices":["Add 98,000 investigators","Measure precision, customer harm and capacity by rule","Remove all controls","Deploy an LLM immediately"],"answer":1,"reason":"A rule-level confusion matrix and operational capacity analysis locate harm and prioritise fixes.","area":"Framing","id":"fraud-2","phase":"Mandate"},{"area":"Evidence & data","title":"Thirty percent or 0.6?","prompt":"Two dashboards report dramatically different fraud rates. The CRO asks which one can anchor resource allocation. What validation would you request?","find":["Customer totals by channel","Case-identity, selected investigation population and matured labels on the same time base","Vendor detection recall from unrelated banks"],"best":1,"why":"Selected review cases do not represent all alerted payments.","exhibit":"100,000 alerts each day; 2,000 high-severity cases receive review. Of those, 600 mature as confirmed fraud. All-alert confirmed count is also 600 assuming complete labels. Other alerts are not fully labelled.","question":"What is the confirmed share among all alerts, conditional on label completeness? (%)","choices":[],"answer":0.6,"reason":"600/100,000=0.6%; 600/2,000=30% reflects the selected high-severity review set and cannot be generalised.","type":"number","unit":"%","tolerance":0.04,"id":"fraud-3","phase":"Mandate"},{"area":"Commercial reasoning","title":"The operating cost no one budgeted","prompt":"Finance praises fraud prevention savings but hasn't counted customer remediation or queue costs. What cost study would you launch?","find":["Per-case investigation minutes, complaint remediation, wrongful customer disruption and preventable loss","Software licence and GPU spending only","Average alert growth from last year"],"best":0,"why":"Optimise total decision harm, not one protection statistic.","exhibit":"Daily work: 2,000 reviews at ₹90 each and 4,000 wrongful blocks generating calls at ₹150 each. Lifetime attrition remains unquantified.","question":"Direct review plus contact-centre cost per day, ₹ lakh?","choices":[],"answer":7.8,"reason":"2,000×₹90=₹1.8 lakh; 4,000×₹150=₹6 lakh. Total ₹7.8 lakh before attrition.","type":"number","unit":"₹ lakh","tolerance":0.08,"id":"fraud-4","phase":"Discovery"},{"title":"Find the high-cost error","prompt":"The CFO asks why customer service costs are rising. Which exhibit do you request?","find":["Customer complaint volumes, false-block costs and confirmed-loss avoidance","Cloud GPU pricing","Number of model features"],"best":0,"why":"To optimise decisions, quantify both sides of the error trade-off.","exhibit":"Each wrongful hard block costs an estimated ₹220 in support and attrition risk. Each fraud prevented avoids ₹3,000 on average. Of 12,000 daily legitimate blocks, 25% can be avoided by switching certain cases to step-up verification.","question":"What is the daily avoided false-block cost from that change alone?","type":"number","answer":6.6,"tolerance":0.1,"unit":"₹ lakh/day","reason":"12,000 × 25% × ₹220 = ₹660,000 = ₹6.6 lakh/day; this excludes verification cost and any resulting extra fraud.","area":"Commercial reasoning","id":"fraud-5","phase":"Discovery"},{"area":"Investigation","title":"A threshold with consequences","prompt":"Risk proposes stringent rules, Operations wants lower customer friction. Which exhibit could distinguish them without privileging either department?","find":["Threshold-specific fraud prevented, wrongful blocks and value of each error","A single aggregated precision score","Average case handling time"],"best":0,"why":"Quantify the frontier between financial crime loss and legitimate-customer harm.","exhibit":"Rule A prevents 140 frauds/day but wrongly blocks 4,000 legitimate payments. Rule B prevents 130 frauds but wrongly blocks 1,300. Prevented fraud value ₹3,000 each, wrongful-block harm ₹220 each.","question":"Relative to A, what is the estimated daily net benefit of B in ₹ lakh?","choices":[],"answer":5.64,"reason":"Avoided wrongful blocks 2,700×₹220=₹5.94 lakh, less 10 lost prevented frauds×₹3,000=₹0.30 lakh. Net ₹5.64 lakh, pending tail-risk review.","type":"number","unit":"₹ lakh","tolerance":0.09,"id":"fraud-6","phase":"Discovery"},{"area":"Evidence & data","title":"A clean-looking validation report","prompt":"A supervised model scores 96% accuracy on the investigated case sample. What would you demand before trusting this for production decisions?","find":["Independent out-of-time test, source-time leakage audit, selection bias analysis and uncertainty intervals","Another random split of the same labelled data","An LLM-generated explanation of the summary accuracy"],"best":0,"why":"Validation cannot rescue post-outcome features or systematic selection bias.","exhibit":"Labels are known after 21 days. Investigators mainly see high-severity alerts. One of the 140 model features is a closure code written after human decision.","question":"Which first corrective action is technically and statistically necessary?","choices":["Tune the decision threshold to 0.5","Remove leakage and construct time-respecting evaluation for the actual population","Increase model parameters","Treat all uninvestigated cases as legitimate"],"answer":1,"reason":"The closure code leaks future information; selected labels and delayed confirmation limit valid generalisation.","id":"fraud-7","phase":"Causal evidence"},{"title":"Protect against a seductive metric","prompt":"A vendor reports 99% accuracy. Which question matters more?","find":["Confusion matrix at operating prevalence and cost-weighted outcomes","The vendor's model parameter count","How polished the dashboard looks"],"best":0,"why":"With rare fraud, global accuracy can be high even when detection is useless.","exhibit":"Fraud is 0.6% of flagged transactions. The proposed model was evaluated on a balanced demo dataset, not a live stream. Calibration and subgroup behaviour are unknown.","question":"Which claim is justified now?","choices":["99% accuracy proves production readiness","The model will stop nearly all fraud","Evidence is insufficient; demand out-of-time evaluation under actual prevalence","Replace all rules today"],"answer":2,"reason":"Evaluation must reflect production prevalence, drift, operational thresholds and loss functions.","area":"Evidence & data","id":"fraud-8","phase":"Causal evidence"},{"area":"Execution","title":"Where the minutes go","prompt":"Analysts claim half their time is wasted searching across systems. Which evidence should precede building an agent?","find":["Time-motion decomposition of retrieval, reasoning, controls and documentation against current integrations","Model latency from an unrelated demo","Only daily case counts"],"best":0,"why":"The business case must target repeatable human time and preserve approval accountability.","exhibit":"Median handling time: 9 minutes gathering records, 5 checking device links, 8 decision and documentation. Current systems offer read-only case APIs. Only an officer may freeze accounts.","question":"What is the safest high-value first automation boundary?","choices":["Unrestricted account freezing by model","Read-only evidence assembly with source links and officer-controlled decisions","Automatic closure of anything below a model threshold","Replace source records with model-written summaries"],"answer":1,"reason":"The measured bottleneck is evidence assembly. Reversible assistance is an appropriate first release.","id":"fraud-9","phase":"Causal evidence"},{"title":"Intervene without losing control","prompt":"Investigators cannot review every flagged event. What should be the first operating-model test?","find":["Tiered queue with shadow scoring and stepped-up verification","Entirely autonomous account closures","Disabling audit trails"],"best":0,"why":"Tiering preserves accountable action while collecting evidence on a more efficient workflow.","exhibit":"Risk approves automated low-impact step-up verification only. Account closures and suspicious-activity decisions remain under human authority.","question":"Which decision boundary fits?","choices":["Agent can close all accounts with high confidence","Model prioritises, policy handles low-impact checks, humans decide high-impact cases","AI replaces AML reviewers entirely","No event may ever be automated"],"answer":1,"reason":"Different impact levels justify different degrees of autonomy. Record overrides and evidence for audit.","area":"AI & controls","id":"fraud-10","phase":"Enablers"},{"area":"Technology design","title":"The audit trail that disappeared","prompt":"A vendor delivers summaries in four seconds, but the bank cannot reconstruct which data or rules produced them. Which design condition blocks approval?","find":["Versioned evidence IDs, role-scoped source access, tool logs, rule/model versions and human sign-off","A lower text-generation price","A higher model context window"],"best":0,"why":"An investigation must be replayable and independently auditable.","exhibit":"The vendor stores only a natural-language conclusion. Current bank policy mandates verifiable source references, change history and an immutable action ledger.","question":"Which minimum technical pattern meets that requirement?","choices":["Governed retrieval through case APIs, versioned policy, immutable events and controlled tool access","Direct agent writes to production accounts with a weekly export","Store the prompt and trust the model answer","Avoid logs because investigations contain sensitive information"],"answer":0,"reason":"The full decision and evidence chain must be controlled and observable, not hidden behind attractive interface latency.","id":"fraud-11","phase":"Enablers"},{"area":"AI & controls","title":"The hidden abstention queue","prompt":"A risk classifier claims 97% precision on confident alerts. The vendor is silent on coverage. Which denominator would you insist on?","find":["Share of all cases accepted versus abstained, errors in both and fallback capacity","Precision within confident cases alone","The model's training cost"],"best":0,"why":"A selective prediction model can meet a headline precision target while shifting most workload to humans.","exhibit":"Of 10,000 cases, 3,000 receive confident recommendations, 7,000 abstain, and staffing supports 5,000 manual reviews.","question":"How many cases exceed review capacity, absent other process changes?","choices":[],"answer":2000,"reason":"7,000−5,000=2,000 unresolved cases. High conditional precision does not establish feasible throughput.","type":"number","unit":"cases","tolerance":0,"id":"fraud-12","phase":"Intervention"},{"title":"Demand an honest trial","prompt":"Operations says the new queue is quicker. Which comparison do you insist on?","find":["Time-to-close and realised loss using randomised or staggered rollout cohorts","Average clicks per case only","The vendor's public marketing case"],"best":0,"why":"Throughput without loss and customer-experience measures can hide risk transfer.","exhibit":"A staggered rollout is feasible across comparable queues. Monitoring includes fraud loss, wrongful blocks, median resolution time and unresolved cases.","question":"Which pilot outcome supports expansion?","choices":["More automated decisions","Lower investigation time, non-inferior loss outcomes, fewer wrongful blocks and complete auditability","Higher model confidence only","Larger alert volume"],"answer":1,"reason":"A defensible gate is multi-objective: efficiency improvement without customer or risk harm.","area":"Execution","id":"fraud-13","phase":"Intervention"},{"area":"Commercial reasoning","title":"The savings that aren't cash","prompt":"A vendor forecasts 10 minutes savings for every alert. Operations sees savings only where relevant data is complete. What benefit assumption should the CFO accept?","find":["Eligible-case fraction × verified net minutes saved × realisable capacity value, less recurring quality cost","Vendor headline saving × 100,000 daily alerts","Savings based only on smaller model size"],"best":0,"why":"The benefit base is investigated eligible cases, not total alert traffic.","exhibit":"2,000 reviews/day, 60% with complete evidence; assistance saves 7 net minutes at ₹4/min. There are 250 working days/year. Costs excluded in this gross estimate.","question":"Gross annual staff-time capacity value, ₹ crore?","choices":[],"answer":0.84,"reason":"2,000×0.60×7×4×250=₹84 lakh=₹0.84 crore. Redeployable minutes are capacity potential, not automatically reduced cash expense.","type":"number","unit":"₹ crore","tolerance":0.025,"id":"fraud-14","phase":"Intervention"},{"title":"Escalation","prompt":"After two weeks, resolution time improves 35%, but confirmed fraud losses rise 18% in treatment queues. How do you respond?","find":["Investigate exposure-normalised losses and pause risky automated steps","Keep scaling to protect the demo","Hide the loss signal until month end"],"best":0,"why":"Risk guardrails override a productivity target; normalise outcomes and stop harmful action while investigating.","exhibit":"Loss increase is above the pre-registered 5% non-inferiority margin; queue mix checks show comparable cohorts.","question":"What is the right governance decision?","choices":["Continue until the tool reaches 50% adoption","Pause the risky action and investigate the loss regression","Declare success based on cycle time","Delete the guardrail"],"answer":1,"reason":"The outcome breached a precommitted guardrail. Halt the relevant action, preserve investigation logs and retest.","area":"Execution","id":"fraud-15","phase":"Boardroom"},{"area":"Execution","title":"A breach of the stop rule","prompt":"On pilot day 14, the system misses one pre-defined high-severity threat. The committee notes average results remain favourable. What is the board-ready response?","find":["A scoped halt and known-good fallback, incident review, clear owner and remediation","Continue until a larger sample dilutes the anomaly","Delete the incident from trend reporting"],"best":0,"why":"Stop rules are pre-committed precisely so the team does not rationalise a severe exception.","exhibit":"The pilot charter requires immediate disablement of any automated routing path associated with a missed high-severity pattern. Reversion to rules and officer review is technically available.","question":"What immediate action is justified?","choices":["Raise the model confidence threshold quietly and continue","Disable the implicated path, activate fallback and investigate before restoration","Scale to more channels for statistical power","Waive the stop condition retrospectively"],"answer":1,"reason":"The documented threshold is binding; safe fallback and evidence-led restoration preserve governance.","id":"fraud-16","phase":"Boardroom"}],"teaser":"A midnight alert. A critical system under pressure. Nobody agrees on what happened."},{"id":"factory","name":"The Perfect Quarter","sector":"INDUSTRIALS · OPERATIONS","role":"Independent operations and capital adviser","mandate":"At fictional Northline Components, bookings, production, inventory and customer promises tell conflicting stories. The CEO must decide which investment and operating changes are worth funding.","skills":["Problem framing","Evidence","Economics","Decision design","Execution"],"steps":[{"area":"Framing","title":"The record quarter","prompt":"Northline Components reports record bookings and rising inventory while key customers demand contractual penalties for late deliveries. Which opening reconciliation do you request?","find":["OTIF, backlog ageing, stock composition, cash tied up and margins by product family","Last quarter's revenue and profit percentage change","The digital factory investment roadmap"],"best":0,"why":"The contradiction concerns physical flow and commercial quality of orders, not just financial totals.","exhibit":"Revenue rose 12%, inventory 28%; on-time-in-full delivery fell from 91% to 78%. Three product families account for 82% of revenue. Aggregate factory utilisation is 72%.","question":"What hypothesis can legitimately be concluded now?","choices":["Excess safety stock definitely causes poor service","The operating system requires product-family flow diagnosis before a capital decision","Weak AI forecasting is the established cause","The factory must permanently cut production"],"answer":1,"reason":"The symptoms establish a paradox, not the root cause. The denominator and flow must be examined by product family and delivery promise.","id":"factory-1","phase":"Mandate"},{"title":"Locate the constraint","prompt":"Inventory rose 24%, but customer orders shipped on time fell from 93% to 81%. What should you inspect?","find":["SKU-level stock position matched to demand and component shortages","Marketing spend","Forecasting AI model names"],"best":0,"why":"Aggregate inventory can rise while the specific bottleneck materials are missing.","exhibit":"Seventy percent of surplus stock sits in slow-moving finished goods; urgent orders depend on three components that frequently arrive late.","question":"Which working hypothesis fits?","choices":["Aggregate inventory is necessarily too low","Product-mix and component availability are misaligned","Every forecast is wrong","Sales needs fewer orders"],"answer":1,"reason":"Total inventory masks SKU-level mismatch. Availability, sequencing and procurement deserve diagnosis.","area":"Framing","id":"factory-2","phase":"Mandate"},{"area":"Evidence & data","title":"An impressive accuracy claim","prompt":"The demand head cites 94% forecast accuracy, and the sales head cites rising shortages. Which test best discriminates between them?","find":["Measure error, bias and volatility at SKU-site-week and replenishment lead-time horizon","Compare monthly company sales versus plan","Ask a generative model to reconcile the two stories"],"best":0,"why":"A high-level forecast does not ensure the parts needed on a given week can be scheduled.","exhibit":"Monthly aggregate forecast accuracy 94%. At the SKU/site/week level weighted absolute error is 31%. Lead times range 2–11 weeks. Stock-outs are concentrated in A components.","question":"What follows from the data?","choices":["The monthly aggregate confirms reliable replenishment","Decision-grain mismatch could explain the contradiction; examine lead-time uncertainty","Suppliers are demonstrably dishonest","Switch all products to build-to-stock"],"answer":1,"reason":"Forecasting must be judged at the horizon and granularity at which planners make orders, not an aggregate accounting period.","id":"factory-3","phase":"Mandate"},{"area":"Commercial reasoning","title":"The stock no one wants","prompt":"Finance believes the stock buildup is temporary. Warehouse managers report inventory older than six months. What exhibit would identify economic exposure?","find":["Raw, work-in-progress and finished goods by age, demand and recoverable value","Gross inventory value alone","The cost of warehouse rent"],"best":0,"why":"Old finished goods and active safety stock imply different remedies.","exhibit":"₹80 crore inventory: ₹25 crore raw, ₹20 crore WIP and ₹35 crore finished. Of the finished stock, ₹12 crore is over 180 days old and can be recovered at an estimated 25% of book value.","question":"What is the approximate book-value loss on liquidating the old finished stock, ₹ crore?","choices":[],"answer":9,"reason":"₹12 crore × 75% unrecovered = ₹9 crore accounting loss. It may release ₹3 crore cash; this isn't ₹12 crore of incremental earnings.","type":"number","unit":"₹ crore","tolerance":0.08,"id":"factory-4","phase":"Discovery"},{"title":"Trace the bottleneck","prompt":"The plant manager blames the forecast. What evidence would distinguish planning failures from supplier unreliability?","find":["Forecast error, lead-time variance, order changes and stockout attribution","Staff cafeteria costs","Industry AI spend estimates"],"best":0,"why":"Causal decomposition prevents investment in prediction when execution creates the bottleneck.","exhibit":"Of 1,000 delayed orders, 530 relate to late supplier components, 270 to production rescheduling and 200 to forecasting error.","question":"Where should the first problem-solving sprint focus?","choices":["Supplier reliability and planning rules","Only a new neural forecaster","Warehouse signage","Customer acquisition"],"answer":0,"reason":"Supplier variability contributes the plurality of delays; it merits targeted remediation first.","area":"Evidence & data","id":"factory-5","phase":"Discovery"},{"area":"Investigation","title":"The 72% utilisation defence","prompt":"The plant director says spare capacity proves staffing and machinery are not binding. How would you test the claim?","find":["Queue, utilisation, downtime and changeover hours by constrained workstation at weekly peak","Company-wide weighted average utilisation over 12 months","A report listing machine asset ages"],"best":0,"why":"Average capacity can hide a peak bottleneck or scheduling instability.","exhibit":"Work-centre C runs at 94% effective peak utilisation. Other centres run 60–75%. C incurs 14 product changeovers/week, each taking 90 minutes.","question":"How many hours of weekly constrained machine time are spent on changeovers?","choices":[],"answer":21,"reason":"14 × 1.5 hours = 21 hours. Re-sequencing might help but requires scenario testing against delivery requirements.","type":"number","unit":"hours","tolerance":0.05,"id":"factory-6","phase":"Discovery"},{"area":"Evidence & data","title":"The supplier with 98% reliability","prompt":"Procurement reports strong vendor compliance. Assembly complains of missing parts. Which denominator is more likely to resolve the conflict?","find":["Complete production kits at required start time, not just purchase orders received by promised date","Invoice match rate as the leading operational indicator","Average payment term by supplier"],"best":0,"why":"A complete assembly needs every required component; partial on-time orders do not suffice.","exhibit":"98% of POs arrive by due date, but just 79% of production kits contain all critical components at release. Three imported components explain most incomplete kits.","question":"Which leading metric should govern weekly production readiness?","choices":["Purchase-order on-time rate alone","Complete-kit availability for the scheduled bill of materials","Number of registered suppliers","Forecast MAPE only"],"answer":1,"reason":"Kit completeness directly represents the joint material constraint at scheduling time.","id":"factory-7","phase":"Causal evidence"},{"title":"Put a price on waste","prompt":"The CFO asks what expedited freight costs. Which records do you obtain?","find":["Emergency shipments, unit premiums and avoidable frequency","Total factory floor area","Model inference latency"],"best":0,"why":"Economic sizing must start from a cost driver that the proposed intervention can actually change.","exhibit":"The factory sends 400 emergency shipments each month at ₹12,000 extra cost per shipment. A supplier-confirmation workflow is estimated to prevent 25% of those events.","question":"What is the potential annual avoided premium before implementation cost?","type":"number","answer":144,"tolerance":1,"unit":"₹ lakh/year","reason":"400 × 12 × 25% × ₹12,000 = ₹14.4 million = ₹144 lakh/year.","area":"Commercial reasoning","id":"factory-8","phase":"Causal evidence"},{"area":"Execution","title":"The spreadsheet handoff","prompt":"A production planner says the supposedly integrated ERP data is wrong half the time. The digital-twin team says it can simulate anyway. What should be instrumented first?","find":["Trusted order IDs, material movements, work-centre events and actual fulfilment timestamps","A photorealistic digital twin interface","Monthly factory dashboards"],"best":0,"why":"A sophisticated simulation built on stale or missing facts creates false precision.","exhibit":"Order demand refreshes daily; line execution is manually entered the following afternoon; inventory adjustments reconcile twice weekly. The operations team can instrument source events in six weeks.","question":"Which minimum viable technical pattern should lead?","choices":["Governed event ingestion and reconciliation to a constrained-scheduling workbench","Global ERP replacement before any controlled test","Unrestricted LLM-generated dispatch instructions","Copy management slides into the data lake"],"answer":0,"reason":"Reliable operational state at decision cadence is the critical enabler, not an automatic preference for new modelling.","id":"factory-9","phase":"Causal evidence"},{"title":"Choose the first fix","prompt":"The vendor offers an expensive optimisation engine. What should be tested before it?","find":["Supplier ETA discipline, reorder parameters and exception ownership","AI-generated meeting notes","A new demand-prediction dashboard"],"best":0,"why":"Reliable inputs and operating routines often deliver substantial gains before optimisation algorithms.","exhibit":"The existing ERP supports lead-time alerts and reorder-policy changes with a ₹9 lakh implementation cost. The proposed AI platform is ₹75 lakh/year.","question":"What is the most defensible next move?","choices":["Sign the AI licence immediately","Pilot the ERP process fix with measurable service and inventory outcomes","Ignore supplier performance","Buy more safety stock everywhere"],"answer":1,"reason":"Start with a cheap, testable intervention aligned to the measured root cause.","area":"AI & controls","id":"factory-10","phase":"Enablers"},{"area":"Technology design","title":"The binding MOQ","prompt":"Analytics shows a better forecasting model, but procurement cannot split supplier lot sizes and operations cannot rebalance shifts. What architecture decision follows?","find":["Couple forecasts with MOQ, lead-time, changeover and labour constraints in an auditable optimiser","Deploy the new prediction API and leave order rules unchanged","Replace planner approval with a language model"],"best":0,"why":"Prediction has little value unless downstream decisions can act within constraints.","exhibit":"A pilot reduces forecast error 22%→18%, but 70% of relevant SKUs have binding minimum-order quantities. No service benefit can yet be isolated from ordinary variance.","question":"Which intervention is commercially better supported?","choices":["Enterprise rollout of the new forecaster on accuracy alone","Controlled test of constrained ordering and sequencing, keeping forecast as one input","No investment in planning capability ever","Automate all purchase orders regardless of MOQ"],"answer":1,"reason":"A forecast is an input to an operating decision. Address constraints, then measure customer and cash outcomes.","id":"factory-11","phase":"Enablers"},{"area":"AI & controls","title":"The autonomous scheduler","prompt":"A vendor proposes an AI agent empowered to change production priorities. Client orders have penalties and quality certifications. Where should its authority stop?","find":["Identify reversible planning recommendations, approval thresholds, quality gates and rollback procedure","Authorise any rescheduling with a high model confidence score","Let the supplier determine decision rights"],"best":0,"why":"Scheduling changes can damage contractual, safety and process commitments.","exhibit":"A recommendation can change shift sequences; expedited orders need finance approval beyond ₹4 lakh; quality lots cannot be bypassed. Planner override and audit are already possible.","question":"What first-release AI role is valid?","choices":["Propose constraint-aware schedule options with simulated service/working-capital effect, subject to planner approval","Directly release uncertified quality lots when confidence is high","Remove rollback to improve speed","Treat offline forecast score as authorisation to reschedule"],"answer":0,"reason":"Start with bounded advisory optimisation and human ownership of material commitments.","id":"factory-12","phase":"Intervention"},{"title":"Map automation authority","prompt":"Planners want a model to autonomously place purchase orders. What constraint should be resolved first?","find":["Supplier contracts, financial delegation and master-data confidence","Colour of dashboard charts","Marketing campaign calendar"],"best":0,"why":"Purchase orders commit money; automation must respect limits and validated data.","exhibit":"The ERP permits auto-replenishment for pre-approved suppliers within budget ceilings; atypical commitments require buyer approval.","question":"Choose the appropriate architecture.","choices":["LLM may commit unlimited purchase orders","Deterministic policy bounds routine reorders; predictive support and human exception review","Keep all data on spreadsheets and remove audits","Model trust replaces purchasing policy"],"answer":1,"reason":"Separate estimation from authority: predictive signals inform decisions; hard limits govern financial actions.","area":"AI & controls","id":"factory-13","phase":"Intervention"},{"area":"Commercial reasoning","title":"The fashionable investment","prompt":"A ₹12 crore work-centre upgrade promises ₹3 crore incremental annual net cash inflow for five end-of-year periods. Which valuation should precede approval?","find":["NPV and sensitivity at cost of capital, residual value and alternative sequencing","Gross output increase without a cash conversion model","Vendor-reported productivity uplift"],"best":0,"why":"Capital allocation must price time, risk and forgone alternatives.","exhibit":"Upfront spend ₹12 crore; five annual end-year cashflows of ₹3 crore; discount rate 10%; no residual value. Five-year annuity factor at 10% = 3.7908.","question":"Approximate project NPV, ₹ crore?","choices":[],"answer":-0.63,"reason":"₹3 crore × 3.7908 − ₹12 crore ≈ −₹0.63 crore. This proposal fails the specified financial hurdle without additional benefits.","type":"number","unit":"₹ crore","tolerance":0.06,"id":"factory-14","phase":"Intervention"},{"title":"Design the measurement","prompt":"The supplier pilot improves one month of fill rate. What additional proof do you need?","find":["Comparison plants or SKUs, inventory holding costs and expedited freight","Number of newly generated forecasts","Number of dashboards delivered"],"best":0,"why":"Service improvements may be purchased by hidden inventory build-up; control for demand mix and cost.","exhibit":"A comparable SKU cohort remains untreated. Treated SKUs show higher on-time fill with unchanged average stock and lower expedition charges.","question":"Which rollout criterion is strongest?","choices":["Improved forecast RMSE alone","Lower total cost per fulfilled order and better service versus control without quality deterioration","More model features","Faster dashboard refresh"],"answer":1,"reason":"Use a total-cost and service counterfactual rather than a single proxy metric.","area":"Execution","id":"factory-15","phase":"Boardroom"},{"area":"Execution","title":"The earnings-call promise","prompt":"Investors expect higher OTIF and lower working capital next quarter. The CEO asks whether to announce a transformation programme now. What commitment is defensible?","find":["Stage a constrained-product pilot with service, cash, exceptions and schedule-adherence gates","Promise plant-wide AI deployment before measuring value","Treat inventory liquidation cash as recurring operating contribution"],"best":0,"why":"No reliable cause-to-economic-result bridge supports a broad unconditional promise.","exhibit":"A six-week family-level pilot can measure OTIF, late-order penalties and stock ageing. Contractual MOQs may delay full capital release despite faster planning.","question":"What should the board authorise?","choices":["A phased process/decision intervention with explicit operating and investment stop criteria","An immediate ₹12 crore machine purchase regardless of NPV","A guaranteed 100% on-time service target","A full generative-AI rollout to every workstation"],"answer":0,"reason":"Fund the experiment that discriminates between constraints and validates economics before approving capex.","id":"factory-16","phase":"Boardroom"}],"teaser":"Every division hit its targets. The CEO has called an emergency meeting."},{"id":"public","name":"The Agency That Automated the Wrong Thing","sector":"PUBLIC SERVICES / RESPONSIBLE AI","role":"Transformation Commissioner","mandate":"At CivicWorks, a benefits agency has a backlog of 80,000 applications. Ministers want an AI approval system in 100 days. You are asked to restore service, preserve due process and defend public value.","skills":["Problem framing","Evidence","Economics","Decision design","Execution"],"steps":[{"title":"Follow the application","prompt":"Elected officials want an approval chatbot. What evidence should you seek before choosing a technology?","find":["Stage-by-stage throughput, rework, eligibility and wait times","Chatbot design trends","How many AI models vendors offer"],"best":0,"why":"A queue grows where arrival volume outstrips effective processing capacity. Mapping stages finds the actual constraint.","exhibit":"The median elapsed time is 38 days, but staff touch-time averages 42 minutes. Sixty percent of applications wait for missing documents; a further 20% wait for inter-agency verification.","question":"Which hypothesis is best supported?","choices":["Every case needs a faster AI eligibility model","Missing-document and verification workflows dominate elapsed time","Human reviewers are inherently slow","The backlog is caused by demand alone"],"answer":1,"reason":"Waiting accounts for most elapsed time; automating final approval cannot remove upstream document delays.","area":"Problem framing"},{"title":"Identify unequal impact","prompt":"Digital-only submission could reduce staff workload. What do you ask to assess fairness?","find":["Channel usage, disability accessibility, language barriers and rejection rates by group","Cloud hosting discounts","Model token prices"],"best":0,"why":"A digital-first strategy can shift costs to applicants and exclude those with poor access.","exhibit":"Twenty-eight percent of claimants rely on assisted filing. Their applications have 1.6× missing-document rates, largely due to unclear forms.","question":"Which response is most defensible?","choices":["Shut assisted filing to force adoption","Redesign forms and offer assisted journeys while measuring subgroup outcomes","Reject assisted claims by default","Launch automated rejection messages"],"answer":1,"reason":"Improve friction without removing access or due process; measure equity and completion.","area":"Evidence"},{"title":"Size the intervention","prompt":"An operations director proposes reminders before submission deadlines. How do you estimate benefit?","find":["Number of affected cases, rework cost and likely reduction from pilot","Vendor brand recognition","AI model benchmark scores"],"best":0,"why":"Value follows from avoided rework, not chatbot message volume.","exhibit":"40,000 incomplete applications require one additional staff touch costing ₹180 each. A randomised reminder pilot reduces these repeat touches by 30%.","question":"What is the estimated avoidable rework cost for this cohort?","type":"number","answer":21.6,"tolerance":0.2,"unit":"₹ lakh","reason":"40,000 × 30% × ₹180 = ₹21.6 lakh.","area":"Economics"},{"title":"Protect due process","prompt":"The minister asks for automatic rejection of incomplete cases. What authority design would you recommend?","find":["Statutory appeal rights, exception handling and consequences of error","Model parameter count","How many citizens own smartphones"],"best":0,"why":"An administrative convenience cannot override legal rights and harm thresholds.","exhibit":"Policy permits automated completeness reminders, but negative eligibility decisions require an accountable officer and an appeal path.","question":"What is the appropriate AI use?","choices":["Autonomous rejection of all incomplete files","Document classification and draft requests, with humans responsible for adverse decisions","No audit trail for speed","Use generative AI to invent missing evidence"],"answer":1,"reason":"Assist low-risk processing, preserve human decision authority, evidence trails and appealability.","area":"Decision design"},{"title":"Investigate a surprising result","prompt":"The new triage workflow reduces average wait by 12 days, but vulnerable applicants now wait longer. What do you request?","find":["Wait-time distributions and outcomes by channel, language and vulnerability group","An average-only performance dashboard","More promotional videos"],"best":0,"why":"Aggregate averages can conceal disparate harm and threshold-based exclusion.","exhibit":"Overall median falls from 38 to 26 days, but assisted-application p90 increases from 65 to 74 days. The new queue ranks easy digital cases first.","question":"What should the steering committee decide?","choices":["Celebrate the mean and scale immediately","Rebalance triage and retest with subgroup protection thresholds","Remove assisted applicants from reports","Replace service metrics with chatbot satisfaction"],"answer":1,"reason":"A service gain that worsens high-need tail outcomes needs correction before scale.","area":"Execution"},{"title":"Set a legitimate success gate","prompt":"Funding depends on a measurable 100-day plan. Which evidence is essential?","find":["Backlog by age, legal time limits, wrongful decisions, appeals and citizen accessibility","AI messages sent","Number of systems bought"],"best":0,"why":"Public value is timeliness, lawful decisions and fair access—not technology throughput.","exhibit":"Auditors can track cohort-specific backlog ageing, appeals and error rates across assisted and digital channels.","question":"Choose the strongest expansion gate.","choices":["75% of staff have used AI once","Backlog ageing improves while error, appeal and access guardrails remain within agreed limits","The chatbot answers 1 million messages","Ministerial press coverage rises"],"answer":1,"reason":"Service, legality and equity must improve together, with documented thresholds and accountable owners.","area":"Execution"}]}];